function croppyNativeShapeOK(path, value) {
  if (path === draftPath) return !!value && typeof value === "object" && !Array.isArray(value);
  if (path === historyPath) return Array.isArray(value);
  return value != null;
}

function readObject(path, fallback) {
  var candidates = [path, path + ".prev"];
  for (var i = 0; i < candidates.length; i++) {
    try {
      var candidate = candidates[i];
      if (!fm.fileExists(candidate)) continue;
      var text = fm.readString(candidate);
      var value = JSON.parse(text);
      if (!croppyNativeShapeOK(path, value)) continue;
      if (i === 1) {
        try { fm.writeString(path, text); } catch (_e) {}
        var kind = path === draftPath ? "draft" : path === historyPath ? "history" : "data";
        if (croppyNativeRecovered.indexOf(kind) < 0) croppyNativeRecovered.push(kind);
      }
      return value;
    } catch (e) {}
  }
  return fallback;
}

function saveJSON(path, text) {
  var tmpPath = path + ".tmp";
  var rollback = null;
  try {
    var parsed = JSON.parse(text);
    if (!croppyNativeShapeOK(path, parsed)) throw new Error("invalid native save shape");
    fm.writeString(tmpPath, text);
    var staged = fm.readString(tmpPath);
    var stagedParsed = JSON.parse(staged);
    if (!croppyNativeShapeOK(path, stagedParsed) || staged !== text) throw new Error("staged native save verification failed");
    try {
      if (fm.fileExists(path)) {
        var current = fm.readString(path);
        var currentParsed = JSON.parse(current);
        if (croppyNativeShapeOK(path, currentParsed)) rollback = current;
      }
    } catch (_e) {}
    if (rollback === null) {
      try {
        if (fm.fileExists(path + ".prev")) {
          var prev = fm.readString(path + ".prev");
          var prevParsed = JSON.parse(prev);
          if (croppyNativeShapeOK(path, prevParsed)) rollback = prev;
        }
      } catch (_e2) {}
    }
    if (rollback !== null) fm.writeString(path + ".prev", rollback);
    fm.writeString(path, staged);
    var finalText = fm.readString(path);
    var finalParsed = JSON.parse(finalText);
    if (!croppyNativeShapeOK(path, finalParsed) || finalText !== staged) throw new Error("final native save verification failed");
    try { if (fm.fileExists(tmpPath) && typeof fm.remove === "function") fm.remove(tmpPath); } catch (_e3) {}
  } catch (e) {
    try { if (rollback !== null) fm.writeString(path, rollback); } catch (_rollbackError) {}
    try { if (fm.fileExists(tmpPath) && typeof fm.remove === "function") fm.remove(tmpPath); } catch (_cleanupError) {}
    console.log("SOULZ save error: " + e);
  }
}

function safeJSON(value) {
  return JSON.stringify(value).replace(/</g, "\\u003c");
}

function croppyHTMLVersion(raw) {
  var m = String(raw || "").match(/CROSS GPT クロッピー\s*\|\s*v(\d+)\.(\d+)\.(\d+)/i);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function croppyCompareVersion(a, b) {
  if (!a && !b) return 0;
  if (!a) return -1;
  if (!b) return 1;
  for (var i = 0; i < 3; i++) {
    if ((a[i] || 0) > (b[i] || 0)) return 1;
    if ((a[i] || 0) < (b[i] || 0)) return -1;
  }
  return 0;
}

function croppyValidHTML(raw) {
  var s = String(raw || "");
  return s.indexOf("<title>CROSS GPT クロッピー | v") >= 0 &&
    s.indexOf('id="keypadWrap"') >= 0 &&
    s.indexOf('id="keypadRepeatBtn"') >= 0 &&
    !!croppyHTMLVersion(s);
}

function croppyWriteVerifiedCache(raw) {
  try {
    if (!croppyValidHTML(raw)) throw new Error("invalid update html");
    fm.writeString(appCacheTempPath, raw);
    var staged = fm.readString(appCacheTempPath);
    if (!croppyValidHTML(staged) || croppyCompareVersion(croppyHTMLVersion(staged), croppyHTMLVersion(raw)) !== 0) throw new Error("staged cache verification failed");
    fm.writeString(appCachePath, staged);
    var finalText = fm.readString(appCachePath);
    if (!croppyValidHTML(finalText) || croppyCompareVersion(croppyHTMLVersion(finalText), croppyHTMLVersion(staged)) !== 0) throw new Error("final cache verification failed");
    try { if (fm.fileExists(appCacheTempPath) && typeof fm.remove === "function") fm.remove(appCacheTempPath); } catch (_e) {}
    return true;
  } catch (e) {
    try { if (fm.fileExists(appCacheTempPath) && typeof fm.remove === "function") fm.remove(appCacheTempPath); } catch (_cleanupError) {}
    console.log("CROPPY cache write error: " + e);
    return false;
  }
}

async function croppyLoadLatestHTML(bundled) {
  var best = bundled;
  var bestVersion = croppyHTMLVersion(bundled);
  croppyUpdateSource = "内蔵";
  croppyUpdateVersion = bestVersion;

  try {
    if (fm.fileExists(appCachePath)) {
      var cached = fm.readString(appCachePath);
      var cachedVersion = croppyHTMLVersion(cached);
      if (croppyValidHTML(cached) && croppyCompareVersion(cachedVersion, bestVersion) >= 0) {
        best = cached;
        bestVersion = cachedVersion;
        croppyUpdateSource = "キャッシュ";
        croppyUpdateVersion = cachedVersion;
      }
    }
  } catch (e) {
    console.log("CROPPY cache read error: " + e);
  }

  try {
    var sep = AUTO_UPDATE_URL.indexOf("?") >= 0 ? "&" : "?";
    var req = new Request(AUTO_UPDATE_URL + sep + "croppy_iphone_update=" + Date.now());
    req.timeoutInterval = fm.fileExists(appCachePath) ? 2.5 : 5;
    req.headers = {"Cache-Control":"no-cache","Pragma":"no-cache","Accept":"text/html"};
    var remote = await req.loadString();
    var remoteVersion = croppyHTMLVersion(remote);
    if (croppyValidHTML(remote) && croppyCompareVersion(remoteVersion, croppyHTMLVersion(bundled)) >= 0 &&
        croppyCompareVersion(remoteVersion, bestVersion) >= 0) {
      best = remote;
      bestVersion = remoteVersion;
      croppyUpdateSource = "最新";
      croppyUpdateVersion = remoteVersion;
      croppyWriteVerifiedCache(remote);
      console.log("CROPPY auto-update: remote v" + bestVersion.join("."));
    }
  } catch (e) {
    console.log("CROPPY auto-update offline: using cached/bundled app");
  }
  return best;
}

